 76→}
 77→
 78→const codexBinaryName = process.platform === "win32" ? "codex.exe" : "codex";
 79→const localVendorRoot = path.join(__dirname, "..", "vendor");
 80→const localBinaryPath = path.join(
 81→  localVendorRoot,
 82→  targetTriple,
 83→  "codex",
 84→  codexBinaryName,
 85→);
 86→
 87→let vendorRoot;
 88→try {
 89→  const packageJsonPath = require.resolve(`${platformPackage}/package.json`);
 90→  vendorRoot = path.join(path.dirname(packageJsonPath), "vendor");
 91→} catch {
 92→  if (existsSync(localBinaryPath)) {
 93→    vendorRoot = localVendorRoot;
 94→  } else {
 95→    const packageManager = detectPackageManager();
 96→    const updateCommand =
 97→      packageManager === "bun"
 98→        ? "bun install -g @openai/codex@latest"
 99→        : "npm install -g @openai/codex@latest";
100→    throw new Error(
101→      `Missing optional dependency ${platformPackage}. Reinstall Codex: ${updateCommand}`,
102→    );
103→  }
104→}
105→
106→if (!vendorRoot) {
107→  const packageManager = detectPackageManager();
108→  const updateCommand =
109→    packageManager === "bun"
110→      ? "bun install -g @openai/codex@latest"
111→      : "npm install -g @openai/codex@latest";
112→  throw new Error(
113→    `Missing optional dependency ${platformPackage}. Reinstall Codex: ${updateCommand}`,
114→  );
115→}
116→
117→const archRoot = path.join(vendorRoot, targetTriple);
118→const binaryPath = path.join(archRoot, "codex", codexBinaryName);
119→
120→// Use an asynchronous spawn instead of spawnSync so that Node is able to
121→// respond to signals (e.g. Ctrl-C / SIGINT) while the native binary is
122→// executing. This allows us to forward those signals to the child process
123→// and guarantees that when either the child terminates or the parent
124→// receives a fatal signal, both processes exit in a predictable manner.
125→
126→function getUpdatedPath(newDirs) {
127→  const pathSep = process.platform === "win32" ? ";" : ":";
128→  const existingPath = process.env.PATH || "";
129→  const updatedPath = [
130→    ...newDirs,
131→    ...existingPath.split(pathSep).filter(Boolean),
132→  ].join(pathSep);
133→  return updatedPath;
134→}
135→
136→/**
137→ * Use heuristics to detect the package manager that was used to install Codex
138→ * in order to give the user a hint about how to update it.
139→ */
140→function detectPackageManager() {
141→  const userAgent = process.env.npm_config_user_agent || "";
142→  if (/\bbun\//.test(userAgent)) {
143→    return "bun";
144→  }
145→
146→  const execPath = process.env.npm_execpath || "";
147→  if (execPath.includes("bun")) {
148→    return "bun";
149→  }
150→
151→  if (
152→    __dirname.includes(".bun/install/global") ||
153→    __dirname.includes(".bun\\install\\global")
154→  ) {
155→    return "bun";
156→  }
157→
158→  return userAgent ? "npm" : null;
159→}
160→
161→const additionalDirs = [];
162→const pathDir = path.join(archRoot, "path");
163→if (existsSync(pathDir)) {
164→  additionalDirs.push(pathDir);
165→}
166→const updatedPath = getUpdatedPath(additionalDirs);
167→
168→const env = { ...process.env, PATH: updatedPath };
169→const packageManagerEnvVar =
170→  detectPackageManager() === "bun"
171→    ? "CODEX_MANAGED_BY_BUN"
172→    : "CODEX_MANAGED_BY_NPM";
173→env[packageManagerEnvVar] = "1";
174→
175→const child = spawn(binaryPath, process.argv.slice(2), {
176→  stdio: "inherit",
177→  env,
178→});
179→
180→child.on("error", (err) => {
181→  // Typically triggered when the binary is missing or not executable.
182→  // Re-throwing here will terminate the parent with a non-zero exit code
183→  // while still printing a helpful stack trace.
184→  // eslint-disable-next-line no-console
185→  console.error(err);
186→  process.exit(1);
187→});
188→
189→// Forward common termination signals to the child so that it shuts down
190→// gracefully. In the handler we temporarily disable the default behavior of
191→// exiting immediately; once the child has been signaled we simply wait for
192→// its exit event which will in turn terminate the parent (see below).
193→const forwardSignal = (signal) => {
194→  if (child.killed) {
195→    return;
196→  }
197→  try {
198→    child.kill(signal);
199→  } catch {
200→    /* ignore */
201→  }
202→};
203→
204→["SIGINT", "SIGTERM", "SIGHUP"].forEach((sig) => {
205→  process.on(sig, () => forwardSignal(sig));
206→});
207→
208→// When the child exits, mirror its termination reason in the parent so that
209→// shell scripts and other tooling observe the correct exit status.
210→// Wrap the lifetime of the child process in a Promise so that we can await
211→// its termination in a structured way. The Promise resolves with an object
212→// describing how the child exited: either via exit code or due to a signal.
213→const childResult = await new Promise((resolve) => {
214→  child.on("exit", (code, signal) => {
215→    if (signal) {
216→      resolve({ type: "signal", signal });
217→    } else {
218→      resolve({ type: "code", exitCode: code ?? 1 });
219→    }
220→  });
221→});
222→
223→if (childResult.type === "signal") {
224→  // Re-emit the same signal so that the parent terminates with the expected
225→  // semantics (this also sets the correct exit code of 128 + n).
226→  process.kill(process.pid, childResult.signal);
227→} else {
228→  process.exit(childResult.exitCode);
229→}
