127→fn parse_completed(
128→    handler: &ConfiguredHandler,
129→    run_result: CommandRunResult,
130→    turn_id: Option<String>,
131→) -> dispatcher::ParsedHandler<UserPromptSubmitHandlerData> {
132→    let mut entries = Vec::new();
133→    let mut status = HookRunStatus::Completed;
134→    let mut should_stop = false;
135→    let mut stop_reason = None;
136→    let mut additional_contexts_for_model = Vec::new();
137→
138→    match run_result.error.as_deref() {
139→        Some(error) => {
140→            status = HookRunStatus::Failed;
141→            entries.push(HookOutputEntry {
142→                kind: HookOutputEntryKind::Error,
143→                text: error.to_string(),
144→            });
145→        }
146→        None => match run_result.exit_code {
147→            Some(0) => {
148→                let trimmed_stdout = run_result.stdout.trim();
149→                if trimmed_stdout.is_empty() {
150→                } else if let Some(parsed) =
151→                    output_parser::parse_user_prompt_submit(&run_result.stdout)
152→                {
153→                    if let Some(system_message) = parsed.universal.system_message {
154→                        entries.push(HookOutputEntry {
155→                            kind: HookOutputEntryKind::Warning,
156→                            text: system_message,
157→                        });
158→                    }
159→                    if parsed.invalid_block_reason.is_none()
160→                        && let Some(additional_context) = parsed.additional_context
161→                    {
162→                        common::append_additional_context(
163→                            &mut entries,
164→                            &mut additional_contexts_for_model,
165→                            additional_context,
166→                        );
167→                    }
168→                    let _ = parsed.universal.suppress_output;
169→                    if !parsed.universal.continue_processing {
170→                        status = HookRunStatus::Stopped;
171→                        should_stop = true;
172→                        stop_reason = parsed.universal.stop_reason.clone();
173→                        if let Some(stop_reason_text) = parsed.universal.stop_reason {
174→                            entries.push(HookOutputEntry {
175→                                kind: HookOutputEntryKind::Stop,
176→                                text: stop_reason_text,
177→                            });
178→                        }
179→                    } else if let Some(invalid_block_reason) = parsed.invalid_block_reason {
180→                        status = HookRunStatus::Failed;
181→                        entries.push(HookOutputEntry {
182→                            kind: HookOutputEntryKind::Error,
183→                            text: invalid_block_reason,
184→                        });
185→                    } else if parsed.should_block {
186→                        status = HookRunStatus::Blocked;
187→                        should_stop = true;
188→                        stop_reason = parsed.reason.clone();
189→                        if let Some(reason) = parsed.reason {
190→                            entries.push(HookOutputEntry {
191→                                kind: HookOutputEntryKind::Feedback,
192→                                text: reason,
193→                            });
194→                        }
195→                    }
196→                } else if trimmed_stdout.starts_with('{') || trimmed_stdout.starts_with('[') {
197→                    status = HookRunStatus::Failed;
198→                    entries.push(HookOutputEntry {
199→                        kind: HookOutputEntryKind::Error,
200→                        text: "hook returned invalid user prompt submit JSON output".to_string(),
201→                    });
202→                } else {
203→                    let additional_context = trimmed_stdout.to_string();
204→                    common::append_additional_context(
205→                        &mut entries,
206→                        &mut additional_contexts_for_model,
207→                        additional_context,
208→                    );
209→                }
210→            }
211→            Some(2) => {
212→                if let Some(reason) = common::trimmed_non_empty(&run_result.stderr) {
213→                    status = HookRunStatus::Blocked;
214→                    should_stop = true;
215→                    stop_reason = Some(reason.clone());
216→                    entries.push(HookOutputEntry {
217→                        kind: HookOutputEntryKind::Feedback,
218→                        text: reason,
219→                    });
220→                } else {
221→                    status = HookRunStatus::Failed;
222→                    entries.push(HookOutputEntry {
223→                        kind: HookOutputEntryKind::Error,
224→                        text: "UserPromptSubmit hook exited with code 2 but did not write a blocking reason to stderr".to_string(),
225→                    });
226→                }
227→            }
228→            Some(exit_code) => {
229→                status = HookRunStatus::Failed;
230→                entries.push(HookOutputEntry {
231→                    kind: HookOutputEntryKind::Error,
232→                    text: format!("hook exited with code {exit_code}"),
233→                });
234→            }
235→            None => {
236→                status = HookRunStatus::Failed;
237→                entries.push(HookOutputEntry {
238→                    kind: HookOutputEntryKind::Error,
239→                    text: "hook exited without a status code".to_string(),
240→                });
241→            }
242→        },
243→    }
244→
245→    let completed = HookCompletedEvent {
246→        turn_id,
247→        run: dispatcher::completed_summary(handler, &run_result, status, entries),
248→    };
249→
250→    dispatcher::ParsedHandler {
251→        completed,
252→        data: UserPromptSubmitHandlerData {
253→            should_stop,
254→            stop_reason,
255→            additional_contexts_for_model,
256→        },
257→    }
258→}
259→
260→fn serialization_failure_outcome(hook_events: Vec<HookCompletedEvent>) -> UserPromptSubmitOutcome {
261→    UserPromptSubmitOutcome {
262→        hook_events,
263→        should_stop: false,
264→        stop_reason: None,
265→        additional_contexts: Vec::new(),
266→    }
267→}
