142→pub fn command_from_argv(argv: &[String]) -> Option<Command> {
143→    let (program, args) = argv.split_first()?;
144→    if program.is_empty() {
145→        return None;
146→    }
147→    let mut command = Command::new(program);
148→    command.args(args);
149→    Some(command)
150→}
