343→fn schema_json<T>() -> anyhow::Result<Vec<u8>>
344→where
345→    T: JsonSchema,
346→{
347→    let schema = schema_for_type::<T>();
348→    let value = serde_json::to_value(schema)?;
349→    let value = canonicalize_json(&value);
350→    Ok(serde_json::to_vec_pretty(&value)?)
351→}
352→
353→fn schema_for_type<T>() -> RootSchema
354→where
355→    T: JsonSchema,
356→{
357→    SchemaSettings::draft07()
358→        .with(|settings| {
359→            settings.option_add_null_type = false;
360→        })
361→        .into_generator()
362→        .into_root_schema_for::<T>()
363→}
364→
365→fn canonicalize_json(value: &Value) -> Value {
366→    match value {
367→        Value::Array(items) => Value::Array(items.iter().map(canonicalize_json).collect()),
368→        Value::Object(map) => {
369→            let mut entries: Vec<_> = map.iter().collect();
370→            entries.sort_by(|(left, _), (right, _)| left.cmp(right));
371→            let mut sorted = Map::with_capacity(map.len());
372→            for (key, child) in entries {
373→                sorted.insert(key.clone(), canonicalize_json(child));
374→            }
375→            Value::Object(sorted)
376→        }
377→        _ => value.clone(),
378→    }
379→}
