 48→pub(crate) fn parse_session_start(stdout: &str) -> Option<SessionStartOutput> {
 49→    let wire: SessionStartCommandOutputWire = parse_json(stdout)?;
 50→    let additional_context = wire
 51→        .hook_specific_output
 52→        .and_then(|output| output.additional_context);
 53→    Some(SessionStartOutput {
 54→        universal: UniversalOutput::from(wire.universal),
 55→        additional_context,
 56→    })
 57→}
