107→pub(crate) fn parse_user_prompt_submit(stdout: &str) -> Option<UserPromptSubmitOutput> {
108→    let wire: UserPromptSubmitCommandOutputWire = parse_json(stdout)?;
109→    let should_block = matches!(wire.decision, Some(BlockDecisionWire::Block));
110→    let invalid_block_reason = if should_block
111→        && match wire.reason.as_deref() {
112→            Some(reason) => reason.trim().is_empty(),
113→            None => true,
114→        } {
115→        Some(invalid_block_message("UserPromptSubmit"))
116→    } else {
117→        None
118→    };
119→    let additional_context = wire
120→        .hook_specific_output
121→        .and_then(|output| output.additional_context);
122→    Some(UserPromptSubmitOutput {
123→        universal: UniversalOutput::from(wire.universal),
124→        should_block: should_block && invalid_block_reason.is_none(),
125→        reason: wire.reason,
126→        invalid_block_reason,
127→        additional_context,
128→    })
129→}
